public abstract class AbstractHelpTest : AbstractGenericTest {

	protected static readonly string HELP_FILENAME_PREFIX = "Fake";
	protected static readonly string HELP_FILENAME = HELP_FILENAME_PREFIX + ".html";

	private Path testTempDir;

	public AbstractHelpTest() : base()
    {
	}

	/* @Before */
	public void setUp()
    {

		testTempDir = Files.createTempDirectory(testName.getMethodName());
	}

	/* @After */
	public void tearDown()
    {
		FileUtilities.deleteDir(testTempDir.toFile());
	}

	protected Path createHelpBuildOutputDir()
    {
		Path @out = testTempDir.resolve("build/help/main/help");
		Files.createDirectories(@out);
		return @out;
	}

	protected Path createFakeHelpTopic(Path helpDir)
    {
		return createFakeHelpTopic("FakeTopic", helpDir);
	}

	protected Path createFakeHelpTopic(string topicName, Path helpDir)
    {
		Path topicsDir = helpDir.resolve("topics");
		Path fakeTopicDir = topicsDir.resolve(topicName);
		Files.createDirectories(fakeTopicDir);
		return fakeTopicDir;
	}

	protected Path createTempHelpDir()
    {
		Path helpDir = testTempDir.resolve("help");
		Files.createDirectory(helpDir);
		return helpDir;
	}

	protected void addRequiredHelpDirStructure(Path helpDir)
    {

		// HelpFile wants to read one of these, so put one there
		createEmpty_TOC_Source_File(helpDir);
		createImageDir(helpDir);
	}

	protected Path createImageDir(Path helpDir)
    {
		Path sharedDir = helpDir.resolve("images");
		Files.createDirectory(sharedDir);

		Path png = sharedDir.resolve("test.png");
		Files.createFile(png);

		return sharedDir;
	}

	protected Path createEmpty_TOC_Source_File(Path dir)
    {

		Path fullTOCPath = dir.resolve("TOC_Source.xml");
		Path file = Files.createFile(fullTOCPath);

		//@formatter:off
	    string TOCXML =  "<?xml version='1.0' encoding='ISO-8859-1' ?>\n" +
	    			     "<!-- Auto-generated on Fri Apr 03 09:37:08 EDT 2015 -->\n\n" +
	    			     
						 "<tocroot>\n" +
						 "</tocroot>\n";
	    //@formatter:on

		Files.write(file, TOCXML.getBytes(), StandardOpenOption.CREATE);
		return file;
	}

	protected Path createHelpContent(Path topic, string anchor)
    {
		Path htmlPath = topic.resolve(HELP_FILENAME);
		Path file = Files.createFile(htmlPath);

		if (anchor == null) {
			anchor = "Default_Anchor";
		}

		//@formatter:off
	    string HTML =
	       "<html>\n" +
		   "<HEAD>\n" +
		   "<TITLE>Configure Tool</TITLE>\n" +
		   "<LINK rel=\"stylesheet\" type=\"text/css\" href=\"help/shared/DefaultStyle.css\">\n" +
		   "</HEAD>\n" +
		   
		   "<BODY>\n" +
		   "    <H1><A name=\""+anchor+"\"></A>Configure Tool</H1>\n" +
		   "    Some text with reference to shared image <IMG src=\"help/shared/note.png\">\n" +
		   "    \n" +
		   "</BODY>\n" +
		   "</HTML>\n";
	    //@formatter:on

		Files.write(file, HTML.getBytes(), StandardOpenOption.CREATE);
		return file;
	}

